/// -S/--smart-case
#[derive(Debug)]
struct SmartCase;

impl Flag for SmartCase {
    fn name_short(&self) -> Option<u8> { Some(b'S') }
    fn name_long(&self) -> &'static str { "smart-case" }
    // ...
    fn update(&self, v: FlagValue, args: &mut LowArgs) -> anyhow::Result<()> {
        assert!(v.unwrap_switch(), "--smart-case flag has no negation");
        args.case = CaseMode::Smart;   // ← sets the case mode
